// Bindings from wrangler.jsonc (Env, generated by `wrangler types`) plus secrets/vars.
export type Bindings = Env & {
  BETTER_AUTH_URL: string;
  BETTER_AUTH_SECRET: string;
  /** encrypts the signing keys stored in the database, and keys the email hashes */
  KEY_ENCRYPTION_SECRET: string;
  GITHUB_ID?: string;
  GITHUB_SECRET?: string;
  GOOGLE_ID?: string;
  GOOGLE_SECRET?: string;
  /** Cloudflare Email Service binding (optional, see wrangler.jsonc). Used instead of Resend when set. */
  EMAIL?: SendEmail;
  RESEND_API_KEY?: string;
  EMAIL_FROM?: string;
  /** comma separated emails of MiddleCat admins (who can set server budgets) */
  MIDDLECAT_ADMINS?: string;
  /** Cloudflare rate limiting binding (optional, see wrangler.jsonc) */
  RATE_LIMITER?: RateLimit;
};

export type AppEnv = { Bindings: Bindings };

/** The public URL of this MiddleCat, used as OIDC issuer. */
export function getIssuer(env: Bindings): string {
  if (!env.BETTER_AUTH_URL) throw new Error("BETTER_AUTH_URL is not configured");
  return env.BETTER_AUTH_URL.replace(/\/+$/, "");
}

export function isAdmin(env: Bindings, email: string) {
  const admins = (env.MIDDLECAT_ADMINS || "").split(",").map((e) => e.trim().toLowerCase());
  return admins.includes(email.trim().toLowerCase());
}
